statfs_encoding u32@36=1,\\n// ABI_bits u32@40=64, zero bytes[44:64]. Exactly two SCM_RIGHTS:\\n// (1) actual open maps in the authenticated peer\'s procfs view, (2) sealed input\\n// snapshot. The factory opens/verifies the actual peer\'s maps independently;\\n// path/metadata claims never come from this request. One request per connection.\\n// Reply: magic[0:8], version u32@8, positive errno u32@12 (zero on success),\\n// zero bytes[16:32]. Success has exactly one SCM_RIGHTS; failure has none.\\n// Both directions use SOCK_SEQPACKET; MSG_TRUNC/MSG_CTRUNC are errors.\\n\\n// Tag header: magic[0:8], version u32@8, total_length u32@12,\\n// path_length u32@16, raw_statfs_encoding u32@20=1. Then kWordCount u64 values, followed\\n// immediately by path_length bytes of the kernel origin readlink target.\\n// The target is nonempty, has no NUL, and is not terminated on the wire.\\n// statfs fsid words preserve the native 32-bit bit pattern, zero-extended.\\nenum TagWord : size_t {\\n  kFactoryUsernsDevice,\\n  kFactoryUsernsInode,\\n  kBackingDevice,\\n  kBackingInode,\\n  kBackingSize,\\n  kOriginTgid,\\n  kOriginStartTicks,\\n  kStatDevice,\\n  kStatInode,\\n  kStatMode,\\n  kStatNlink,\\n  kStatUid,\\n  kStatGid,\\n  kStatRdev,\\n  kStatSize,\\n  kStatBlockSize,\\n  kStatBlocks,\\n  kStatAtimeSeconds,\\n  kStatAtimeNanoseconds,\\n  kStatMtimeSeconds,\\n  kStatMtimeNanoseconds,\\n  kStatCtimeSeconds,\\n  kStatCtimeNanoseconds,\\n  kFsType,\\n  kFsBlockSize,\\n  kFsBlocks,\\n  kFsBlocksFree,\\n  kFsBlocksAvailable,\\n  kFsFiles,\\n  kFsFilesFree,\\n  kFsId0,\\n  kFsId1,\\n  kFsNameLength,\\n  kFsFragmentSize,\\n  kFsFlags,\\n  kFsSpare0,\\n  kFsSpare1,\\n  kFsSpare2,\\n  kFsSpare3,\\n  kWordCount\\n};\\ninline constexpr size_t kTagHeaderBytes = 24 + 8 * kWordCount;\\ninline constexpr size_t kMaxTagBytes = kTagHeaderBytes + kMaxPathBytes;\\n\\nstruct Origin {\\n  uint64_t words[kWordCount]{};\\n  char path[kMaxPathBytes]{};\\n  size_t path_size = 0;\\n};\\n\\nenum class Lookup { kOrdinary, kVirtual, kError };\\n\\n\\nuint32_t GetU32(const unsigned char* bytes);\\nuint64_t GetU64(const unsigned char* bytes);\\nvoid PutU32(unsigned char* bytes, uint32_t value);\\nvoid PutU64(unsigned char* bytes, uint64_t value);\\nbool DecodeOrigin(const unsigned char* bytes, size_t size, Origin* origin);\\nbool DecodeStat(const Origin& origin, struct stat* result);\\nbool DecodeKernelStatfs(const Origin& origin, KernelStatfs* result);\\nbool DecodeStatfs(const Origin& origin, struct statfs* result);\\nsize_t EncodeOrigin(const Origin& origin, unsigned char* output, size_t capacity);\\nstruct CreateRequest {\\n  uint64_t payload_size{};\\n  uint32_t caller_tid{};\\n  uint32_t source_flags{};\\n  uint32_t original_fd_flags{};\\n};\\nbool DecodeCreateRequest(const unsigned char* bytes, size_t size, CreateRequest* request);\\nbool EncodeCreateRequest(const CreateRequest& request, unsigned char output[kRequestBytes]);\\nvoid EncodeReply(uint32_t error, unsigned char output[kReplyBytes]);\\n\\n}  // namespace berberis::proc_maps_provenance\\n#if defined(__GNUC__)\\n#pragma GCC visibility pop\\n#endif\\n#endif\\n", "include/berberis/kernel_api/proc_maps_kernel_statfs.h": "// SPDX-License-Identifier: Apache-2.0\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_KERNEL_STATFS_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_KERNEL_STATFS_H_\\n\\n#include <stddef.h>\\n#include <stdint.h>\\n#include <string.h>\\n#include <sys/statfs.h>\\n#include <type_traits>\\n\\nnamespace berberis::proc_maps_provenance {\\n\\n// Linux asm-generic/statfs.h LP64 raw-syscall representation, shared by\\n// x86_64 and arm64. These members retain kernel bits, not libc semantics.\\n// Never construct it by adding flags to an already-normalized libc result.\\nstruct KernelStatfs {\\n  uint64_t f_type{}, f_bsize{}, f_blocks{}, f_bfree{}, f_bavail{};\\n  uint64_t f_files{}, f_ffree{};\\n  uint32_t f_fsid[2]{};\\n  uint64_t f_namelen{}, f_frsize{}, f_flags{}, f_spare[4]{};\\n};\\nstatic_assert(sizeof(long) == 8);\\nstatic_assert(std::is_standard_layout_v<KernelStatfs>);\\nstatic_assert(std::is_trivially_copyable_v<KernelStatfs>);\\nstatic_assert(sizeof(KernelStatfs) == 120 && alignof(KernelStatfs) == 8);\\nstatic_assert(sizeof(struct statfs) == sizeof(KernelStatfs));\\n#define BERBERIS_CHECK_KERNEL_STATFS_FIELD(field, offset, bytes) \\\\\\n  static_assert(offsetof(KernelStatfs, field) == offset); \\\\\\n  static_assert(sizeof(KernelStatfs::field) == bytes); \\\\\\n  static_assert(offsetof(struct statfs, field) == offset); \\\\\\n  static_assert(sizeof(((struct statfs*)nullptr)->field) == bytes)\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_type, 0, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_bsize, 8, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_blocks, 16, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_bfree, 24, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_bavail, 32, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_files, 40, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_ffree, 48, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_fsid, 56, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_namelen, 64, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_frsize, 72, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_flags, 80, 8);\\nBERBERIS_CHECK_KERNEL_STATFS_FIELD(f_spare, 88, 32);\\n#undef BERBERIS_CHECK_KERNEL_STATFS_FIELD\\n\\n// Caller-side conversion only. The fixed worker writes KernelStatfs directly.\\n// The host libc ABI has the asserted layout above, but Bionic\'s successful\\n// fstatfs wrapper clears ST_VALID. Preserve every other bit and raw snapshot.\\ninline void KernelStatfsToLibc(const KernelStatfs& kernel, struct statfs* result) {\\n  memcpy(result, &kernel, sizeof(kernel));\\n#if defined(__BIONIC__)\\n  result->f_flags &= ~0x0020;\\n#endif\\n}\\n}  // namespace berberis::proc_maps_provenance\\n#endif\\n", "include/berberis/kernel_api/proc_maps_linux_compat.h": "// SPDX-License-Identifier: Apache-2.0\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_LINUX_COMPAT_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_LINUX_COMPAT_H_\\n\\n// The host-test compiler uses the pinned glibc 2.17 sysroot. Its Linux UAPI\\n// headers predate memfd, namespace descriptors and pidfds. Keep the kernel ABI\\n// constants available without importing a different host\'s headers or changing\\n// the runtime checks. A missing kernel implementation still returns ENOSYS.\\n#include <fcntl.h>\\n#include <linux/magic.h>\\n#include <sys/ioctl.h>\\n#include <sys/syscall.h>\\n\\n#if __has_include(<linux/memfd.h>)\\n#include <linux/memfd.h>\\n#endif\\n#if __has_include(<linux/nsfs.h>)\\n#include <linux/nsfs.h>\\n#endif\\n\\n// include/uapi/linux/memfd.h, include/uapi/linux/nsfs.h,\\n// include/uapi/linux/magic.h and include/uapi/linux/fcntl.h.\\n#ifndef MFD_CLOEXEC\\n#define MFD_CLOEXEC 0x0001U\\n#endif\\n#ifndef MFD_ALLOW_SEALING\\n#define MFD_ALLOW_SEALING 0x0002U\\n#endif\\n#ifndef NS_GET_NSTYPE\\n#define NS_GET_NSTYPE _IO(0xb7, 0x3)\\n#endif\\n#ifndef NSFS_MAGIC\\n#define NSFS_MAGIC 0x6e736673\\n#endif\\n#ifndef F_ADD_SEALS\\n#define F_ADD_SEALS 1033\\n#endif\\n#ifndef F_GET_SEALS\\n#define F_GET_SEALS 1034\\n#endif\\n\\nstatic_assert(MFD_CLOEXEC == 0x0001U && MFD_ALLOW_SEALING == 0x0002U);\\nstatic_assert(NS_GET_NSTYPE == _IO(0xb7, 0x3) && NSFS_MAGIC == 0x6e736673);\\nstatic_assert(F_ADD_SEALS == 1033 && F_GET_SEALS == 1034);\\n\\n// arch/x86/entry/syscalls/syscall_64.tbl. Do not apply LP64 x86 syscall\\n// numbers to x32 or a different host ABI. The raw owner already requires this\\n// same host ABI. Prefer existing declarations and assert their exact values.\\n#if defined(__x86_64__) && !defined(__ILP32__)\\n#ifndef SYS_memfd_create\\n#define SYS_memfd_create 319\\n#endif\\n#ifndef SYS_pidfd_open\\n#define SYS_pidfd_open 434\\n#endif\\n#ifndef SYS_close_range\\n#define SYS_close_range 436\\n#endif\\n#ifndef SYS_pidfd_getfd\\n#define SYS_pidfd_getfd 438\\n#endif\\nstatic_assert(SYS_memfd_create == 319 && SYS_pidfd_open == 434);\\nstatic_assert(SYS_close_range == 436 && SYS_pidfd_getfd == 438);\\n#endif\\n\\n#endif  // BERBERIS_KERNEL_API_PROC_MAPS_LINUX_COMPAT_H_\\n", "include/berberis/kernel_api/proc_maps_snapshot_reopen.h": "// SPDX-License-Identifier: Apache-2.0\\n#ifndef BERBERIS_KERNEL_API_PROC_MAPS_SNAPSHOT_REOPEN_H_\\n#define BERBERIS_KERNEL_API_PROC_MAPS_SNAPSHOT_REOPEN_H_\\n\\n#include <errno.h>\\n#include <fcntl.h>\\n#include <stddef.h>\\n#include <stdint.h>\\n#include <sys/syscall.h>\\n#include <unistd.h>\\n\\nnamespace droidloom::proc_maps_factory {\\n\\n// Only the trusted factory\'s own freshly created, held and sealed memfd may\\n// reach this helper. It never accepts a file handle or mount identifier from\\n// the peer. Callers retain their complete final inode, seal, tag, offset and\\n// exact F_GETFL checks before publication.\\n//\\n// A proc-fd magic link cannot be opened with O_NOFOLLOW. Reopening the same\\n// inode by its kernel-produced handle avoids that lookup and preserves the\\n// actual file-status bit. In particular, do not clear the bit or simulate it\\n// in a returned status value. Kernel support and the factory\'s existing\\n// CAP_DAC_READ_SEARCH are required; this entry never changes credentials or\\n// policy, and propagates failures without a different opening fallback.\\ninline int ReopenOwnSnapshotByHandle(int descriptor, int status_flags) {\\n  if (!(status_flags & O_NOFOLLOW) ||\\n      (status_flags & (O_ACCMODE | O_PATH)) != O_RDONLY) {\\n    errno = EINVAL;\\n    return -1;\\n  }\\n#if defined(SYS_name_to_handle_at) && defined(SYS_open_by_handle_at)\\n  // Linux struct file_handle ABI, with the fixed MAX_HANDLE_SZ bound. Avoid a\\n  // C++ flexible-array extension or relying on a libc struct declaration.\\n  struct Handle {\\n    uint32_t bytes;\\n    int32_t type;\\n    unsigned char data[128];\\n  } handle{};\\n  static_assert(offsetof(Handle, data) == 8 && sizeof(Handle) == 136);\\n  handle.bytes = sizeof(handle.data);\\n  int mount_id = 0;\\n  if (syscall(SYS_name_to_handle_at, static_cast<long>(descriptor), \\"\\", &handle,\\n              &mount_id, static_cast<unsigned long>(AT_EMPTY_PATH)) < 0) return -1;\\n  if (!handle.bytes || handle.bytes > sizeof(handle.data) || handle.type < 0) {\\n    errno = EPROTO;\\n    return -1;\\n  }\\n  // The internal shmem mount can have legacy mount_id zero. The same held\\n  // descriptor supplies the mount; no mount-table/path reconstruction occurs.\\n  return static_cast<int>(syscall(SYS_open_by_handle_at, static_cast<long>(descriptor),\\n                                  &handle, static_cast<unsigned long>(\\n                                      static_cast<unsigned int>(status_flags | O_CLOEXEC))));\\n#else\\n  errno = ENOSYS;\\n  return -1;\\n#endif\\n}\\n\\n}  // namespace droidloom::proc_maps_factory\\n#endif  // BERBERIS_KERNEL_API_PROC_MAPS_SNAPSHOT_REOPEN_H_\\n", "listener-source-pins.json": "{\\n  \\"files\\": [\\n    {\\n      \\"bytes\\": 661,\\n      \\"git_blob_sha1\\": \\"c5a166382c60f820dfd2f8f524b7bddcc3d4807b\\",\\n      \\"path\\": \\"DEPENDENCY_BINDING.json\\",\\n      \\"sha256\\": \\"ee95fcab99195507d4bba77309bb6b39d05e022f1165edc5a1334dfe650f8add\\"\\n    },\\n    {\\n      \\"bytes\\": 3014,\\n      \\"git_blob_sha1\\": \\"36617c16368d3913fe3bc65ae13bb6c54960ef8a\\",\\n      \\"path\\": \\"README.md\\",\\n      \\"sha256\\": \\"f1da019e7ad016c7843a4d172a4763668a0b38c3c74b000a39266b1e8ddd09f5\\"\\n    },\\n    {\\n      \\"bytes\\": 26498,\\n      \\"git_blob_sha1\\": \\"5053ee5bc0942a6de04294f087fa313cebe655ce\\",\\n      \\"path\\": \\"controls/admission_controls.cc\\",\\n      \\"sha256\\": \\"89d1efb34d449494bd4138d7c590406b8fda5878bb045408cb7ad6c002e74d46\\"\\n    },\\n    {\\n      \\"bytes\\": 10084,\\n      \\"git_blob_sha1\\": \\"27abd6074cf8b09909eacc544bdd209288ce4671\\",\\n      \\"path\\": \\"controls/admission_response_controls.cc\\",\\n      \\"sha256\\": \\"bcb287f7b6bdc94a9261f6c4da70bd5cb84ae329e23a3250717e3466696917b6\\"\\n    },\\n    {\\n      \\"bytes\\": 8615,\\n      \\"git_blob_sh